class Solution {
  public int maxDistance(int side, int[][] points, int k) {
    int n = points.length;
    long[] keyed = new long[n];
    for (int i = 0; i < n; i++) {
      int x = points[i][0], y = points[i][1];
      long pos;
      if (y == 0) pos = x;
      else if (x == side) pos = (long) side + y;
      else if (y == side) pos = 2L * side + (side - x);
      else pos = 3L * side + (side - y);
      keyed[i] = pos * 20000 + i;
    }
    java.util.Arrays.sort(keyed);
    int[] xs = new int[n], ys = new int[n];
    for (int i = 0; i < n; i++) {
      int id = (int) (keyed[i] % 20000);
      xs[i] = points[id][0];
      ys[i] = points[id][1];
    }
    int lo = 1, hi = 2 * side;
    while (lo < hi) {
      int mid = (lo + hi + 1) >>> 1;
      if (feasible(xs, ys, k, mid)) lo = mid;
      else hi = mid - 1;
    }
    return lo;
  }

  private static int dist(int[] xs, int[] ys, int a, int b) {
    return Math.abs(xs[a] - xs[b]) + Math.abs(ys[a] - ys[b]);
  }

  private static boolean feasible(int[] xs, int[] ys, int k, int d) {
    int n = xs.length;
    int[] nxt = new int[n];
    int j = 0;
    for (int i = 0; i < n; i++) {
      if (j < i + 1) j = i + 1;
      while (j < i + n && dist(xs, ys, i, j % n) < d) j++;
      nxt[i] = j;
    }
    for (int s = 0; s < n; s++) {
      int cur = s;
      boolean ok = true;
      for (int t = 1; t < k; t++) {
        int nx = nxt[cur % n] + cur - cur % n;
        if (nx >= s + n) {
          ok = false;
          break;
        }
        cur = nx;
      }
      if (ok && dist(xs, ys, cur % n, s) >= d) return true;
    }
    return false;
  }
}
